import { useState, type FormEvent } from 'react';
import { JxButton, JxInput, JxToast } from '@jinx-ui/react';

// JxInput/JxToast prop names follow the value+onValueChange / open+onOpenChange
// convention from the README; verify against the package's typings.
export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [toastOpen, setToastOpen] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim()) return;
    setEmail('');
    setToastOpen(true);
  };

  return (
    <>
      <form
        className="jx-stack"
        style={{ gap: 'var(--jx-space-3)' }}
        onSubmit={handleSubmit}
        noValidate={false}
      >
        <JxInput
          type="email"
          name="email"
          required
          label="Электронная почта"
          placeholder="you@example.com"
          value={email}
          onValueChange={setEmail}
        />
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </form>

      <JxToast
        open={toastOpen}
        onOpenChange={setToastOpen}
        placement="bottom-right"
        variant="success"
        duration={4000}
        title="Готово"
        description="Письмо отправлено — проверьте почту и подтвердите подписку."
      />
    </>
  );
}

